30		<style>
31			:root {
32				color-scheme: light dark;
33				--text: #1a1a1a;
34				--text-secondary: #555;
35				--background: #fff;
36				--accent: #0052a3;
37				--border: #e0e0e0;
38			}
39			@media (prefers-color-scheme: dark) {
40				:root {
41					--text: #e0e0e0;
42					--text-secondary: #a0a0a0;
43					--background: #121212;
44					--accent: #5fa3ff;
45					--border: #333;
46				}
47			}
48			*,
49			*::before,
50			*::after {
51				box-sizing: border-box;
52			}
53			html {
54				-webkit-text-size-adjust: 100%;
55				text-size-adjust: 100%;
56			}
57			@media (prefers-reduced-motion: no-preference) {
58				html {
59					scroll-behavior: smooth;
60				}
61				a {
62					transition: text-decoration-thickness 0.15s ease;
63				}
64				.skip-link {
65					transition: transform 0.15s ease;
66				}
67			}
68			body {
69				display: grid;
70				grid-template-rows: auto 1fr auto;
71				min-height: 100vh;
72				min-height: 100dvh;
73				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
74				font-size: 1rem;
75				line-height: 1.6;
76				max-width: 70ch;
77				margin: 0 auto;
78				padding: clamp(1rem, 5vw, 1.5rem);
79				padding-top: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-top));
80				padding-right: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-right));
81				padding-bottom: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-bottom));
82				padding-left: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-left));
83				color: var(--text);
84				background: var(--background);
85			}
86			h1 {
87				color: var(--accent);
88				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
89				font-weight: 700;
90				line-height: 1.1;
91				text-wrap: balance;
92				margin: 0 0 1.5rem 0;
93				letter-spacing: -0.02em;
94			}
95			p {
96				text-wrap: pretty;
97				margin: 1rem 0;
98			}
99			a {
100				color: var(--accent);
101				text-underline-offset: 0.2em;
102				text-decoration-thickness: 2px;
103				text-decoration-skip-ink: auto;
104				font-weight: 500;
105			}
106			a:hover, a:active {
107				text-decoration-thickness: 3px;
108			}
109			:focus-visible {
110				outline: 2px solid var(--accent);
111				outline-offset: 2px;
112				border-radius: 2px;
113			}
114			button:focus-visible, a:focus-visible {
115				box-shadow: 0 0 0 3px var(--background), 0 0 0 5px var(--accent);
116				outline: none;
117			}
118			.skip-link {
119				position: absolute;
120				left: 0;
121				top: 0;
122				transform: translateY(-100%);
123				background: var(--accent);
124				color: var(--background);
125				padding: 0.75rem 1.5rem;
126				z-index: 1000;
127				border-radius: 0 0 0.25rem 0;
128				font-weight: 600;
129				text-decoration: none;
130				display: inline-block;
131			}
132			.skip-link:focus {
133				transform: none;
134				outline: 3px solid var(--text);
135				outline-offset: -3px;
136			}
137			header {
138				padding-block: 1.5rem 0;
139			}
140			main {
141				padding: 1rem 0;
142			}
143			main:focus {
144				outline: none;
145			}
146			footer {
147				padding-block: 1.5rem;
148				margin-top: 3rem;
149				border-top: 1px solid var(--border);
150				font-size: 0.875rem;
151				color: var(--text-secondary);
152				text-align: center;
153			}
154			footer p {
155				margin: 0.5rem 0;
156			}
157			@media print {
158				.skip-link {
159					display: none;
160				}
161				body {
162					display: block;
163					min-height: 0;
164					max-width: none;
165					padding: 0;
166				}
167				a {
168					color: inherit;
169					text-decoration: underline;
170				}
171				a[href^="http"]::after {
172					content: " (" attr(href) ")";
173					font-size: 0.85em;
174					font-weight: normal;
175				}
176			}
177		</style>
178	</head>
179	<body>
180		<a class="skip-link" href="#main" aria-label="Skip to main content">Skip to content</a>
181		<header>
182			<h1>Welcome</h1>
183		</header>
184		<main id="main" tabindex="-1">
185			<p>This is a well-structured, accessible HTML5 document.</p>
186			<p>
187				It uses semantic landmarks, a skip link for keyboard navigation,
188				and CSS that adapts to your light or dark mode preference.
189			</p>
190			<p>
191				Text and link colors meet WCAG AA contrast in both themes, type scales
192				with your browser's font size, and motion respects your system settings.
193			</p>
194		</main>
195		<footer>
196			<p><small>&copy; <time datetime="2026">2026</time>. All rights reserved.</small></p>
197		</footer>
198	</body>
199	</html>
